#!/usr/bin/env node
// FT9: boundary audit — categorizes every file in the shadless repo as
// PROGRAMMATIC (regenerated by tools on `make build`) vs HAND-AUTHORED
// (LLM/human edits expected, no script owns them), and surfaces explicit
// LLM PATCH POINTS inside tool source.
//
// Two modes:
//   (default)   human-readable report; exit 0 always
//   --strict     JSON to stdout, exit 1 on drift (tool-generated file
//                modified outside its source tool)
//
// Path heuristics are the source of truth — each pattern documents
// which tool owns the output and what it generates from. To extend:
// add the new pattern to PROGRAMMATIC_PATTERNS / HAND_AUTHORED_PATTERNS
// below with the owning tool name and source file reference.
//
// LLM PATCH POINTS are explicit (curated) regions inside otherwise-
// programmatic tool source where a human is expected to intervene. These
// are NOT regenerated automatically — they're the seam between script
// and human work.
import { readdirSync, readFileSync, statSync } from "node:fs"
import { execSync } from "node:child_process"
import { join } from "node:path"

// ---------- categorization ---------------------------------------------------
// Three categories:
//   PROGRAMMATIC  — regenerated by tools on `make build`
//   TOOL SOURCE    — hand-written code that owns the PROGRAMMATIC outputs
//   HAND-AUTHORED  — LLM/human content (vendor files, demos, docs prose,
//                    pin tracking); LLM patch points inside tool source
//                    are flagged separately in LLM_PATCH_POINTS below
//
// Patterns are matched first-match-wins. Order matters.

const TOOL_SOURCE_PATTERNS = [
  { test: (p) => /^tools\/.*\.mjs$/.test(p),
    note: "tools/*.mjs — builder tools + gates (build-demo, build-rtl, demo, docs-*, etc.); gates/*.mjs — the pipeline graph, meta, ledger, overlay, upstream drill" },
  { test: (p) => /^src\/converter\/.*\.mjs$/.test(p),
    note: "src/converter/*.mjs — registry .tsx → IR JSON (src/registry/ir/*.json)" },
  { test: (p) => /^src\/emitter\/.*\.mjs$/.test(p),
    note: "src/emitter/*.mjs — IR JSON → dist/components/*.html + slot CSS" },
  { test: (p) => /^src\/docs\/.*\.mjs$/.test(p),
    note: "src/docs/*.mjs — JSX/runtime used by the MDX compile step (ComponentPreview, code-copy/view-code/rtl handlers, theme pre-paint, etc.)" },
  { test: (p) => /^src\/runtime\/.*\.(mjs|js)$/.test(p),
    note: "src/runtime/*.mjs|js — interactive runtime copied into dist/ as shadless.js" },
  { test: (p) => p === "src/tags.mjs",
    note: "src/tags.mjs — tag normalization shared by converter/emitter/css" },
]

const PROGRAMMATIC_PATTERNS = [
  // IR (converter)
  { test: (p) => p.startsWith("src/registry/ir/") && p.endsWith(".json"),
    tool: "src/converter/index.mjs", source: "apps/v4/registry/bases/radix/ui/*.tsx" },
  // dist/components — emitter + build-demo + build-rtl + demo (multi-source)
  { test: (p) => p.startsWith("dist/components/") && p.endsWith(".html") && !/-rtl-(en|he|fa)\.html$/.test(p) && p !== "dist/components/alert-demo.html",
    tool: "src/emitter/index.mjs OR tools/demo.mjs (per-tier fixture)",
    source: "src/registry/ir/*.json + probes/t{6,7,8,9}/* (per tier)" },
  { test: (p) => p === "dist/components/alert-demo.html",
    tool: "tools/build-demo.mjs", source: "examples/radix/alert-demo.tsx" },
  { test: (p) => p.startsWith("dist/components/") && /-rtl-(en|he|fa)\.html$/.test(p),
    tool: "tools/build-rtl.mjs", source: "examples/aria/<name>-rtl.tsx" },
  // docs/demos — build-rtl writes here too (so the host page can serve
  // the iframes even before docs-build copies them into docs/site/).
  { test: (p) => p.startsWith("docs/demos/") && /-rtl-(en|he|fa)\.html$/.test(p),
    tool: "tools/build-rtl.mjs", source: "examples/aria/<name>-rtl.tsx" },
  // dist CSS / JS — tailwind + copy
  { test: (p) => ["dist/out.css", "dist/globals.css", "dist/shadless.css", "dist/shadless-core.css"].includes(p),
    tool: "npx @tailwindcss/cli (via make demo / make docs)", source: "dist/components/*.html + shadless CSS fixes" },
  // J2 product surface — per-component @apply sources + tokens + compiled
  { test: (p) => p.startsWith("dist/css/") && p.endsWith(".css"),
    tool: "tools/demo.mjs (parts) + tools/product-css.mjs (tokens)", source: "src/registry/ir/*.json + probes/h4/globals.css" },
  { test: (p) => ["dist/shadless.product.css", "dist/shadless.full.css", "dist/shadless.full.min.css"].includes(p),
    tool: "tools/product-css.mjs + npx @tailwindcss/cli", source: "dist/css/* (tokens + component parts + fixes)" },
  // J4: server-stack template macros — regenerated from IR
  { test: (p) => ["dist/shadless.js", "dist/shadless.min.js"].includes(p),
    tool: "tools/build-js.mjs", source: "vendor/radix-kernel.iife.js + src/runtime/core.js" },
  { test: (p) => (p.startsWith("dist/js/") || p.startsWith("dist/esm/")) && /\.(m?js|d\.ts)$/.test(p),
    tool: "tools/build-js.mjs", source: "src/runtime/core.js + src/runtime/components/*.js + src/runtime/shadless.d.ts + vendor/*.iife.js" },
  { test: (p) => p === "dist/demo-index.html",
    tool: "tools/demo.mjs", source: "per-tier IR list (built into demo.mjs)" },
  // docs/site — docs-build output
  { test: (p) => p.startsWith("docs/site/") && (p.endsWith(".html") || p.endsWith(".css") || p.endsWith(".js")),
    tool: "tools/docs-build.mjs", source: "apps/v4/content/docs/components/*/*.mdx (compiled via MDX)" },
  { test: (p) => p === "build/rtl-langs.json",
    tool: "tools/build-rtl.mjs", source: "examples/aria/*-rtl.tsx" },
  // catalog + reports
  { test: (p) => p === "docs/catalog.json",
    tool: "tools/docs-catalog.mjs", source: ".upstream/.../components/*/*.mdx + dist/components state" },
  // (patches/ overlay retired — manual interventions live in overlays/ + src/)
]

const HAND_AUTHORED_PATTERNS = [
  // Vendor files (vendored from upstream release artifacts)
  { test: (p) => p === "vendor/radix-kernel.iife.js", owner: "human (vendor)" },
  { test: (p) => p === "vendor/embla-carousel.iife.js", owner: "human (vendor)" },
  // docs/demos — Arabic RTL defaults + 259 variant demos (FT7 batches)
  { test: (p) => p.startsWith("docs/demos/") && /-rtl\.html$/.test(p),
    owner: "human (FT7 Arabic RTL defaults)" },
  { test: (p) => p.startsWith("docs/demos/") && !/-rtl/.test(p),
    owner: "human (FT7 hand-authored demos)" },
  // Guide source content (consumed by docs-build)
  { test: (p) => p.startsWith("docs/content/") && p.endsWith(".mdx"),
    owner: "human (guide source — compiled by docs-build into docs/site/)" },
  { test: (p) => p === "docs/content-map.json",
    owner: "human (FT7 build state)" },
  { test: (p) => p === "tools/git-hooks/pre-commit",
    owner: "human (git hook shell script)" },
  // Pin tracking
  { test: (p) => p === "src/registry/pin.json",
    owner: "gates/upstream.mjs (re-pin) / human (vendor re-hash via tools/pin.mjs --force)" },
  // Docs / orchestration (mix of programmatic generation and human prose)
  { test: (p) => ["Makefile", "README.md", "UPGRADING.md", "package.json", ".gitignore", "package-lock.json"].includes(p)
    || /^FINDING-.*\.md$/.test(p),
    owner: "human (orchestration + narrative)" },
  // Probe fixtures — used by emit/demo as references, but hand-written
  { test: (p) => p.startsWith("probes/"),
    owner: "human (test fixtures; some consumed by tools/demo.mjs)" },
]

// LLM PATCH POINTS — curated regions inside tool source where humans
// intervene. format: { file, lines, what }.
const LLM_PATCH_POINTS = [
  {
    file: "tools/build-rtl.mjs",
    lines: "32-37",
    what: "PERSIAN translations dict — 4 keys × 2 alerts for alert-rtl only. Upstream ships en/ar/he; Persian isn't in upstream so hand-coded. When upstream adds a new language, add it here (or generalize to read from upstream).",
  },
  {
    file: "tools/build-demo.mjs",
    lines: "~158",
    what: "EMITTERS map — one entry per <name>-demo.tsx. Currently only alert-demo.tsx is wired. Add new entries to extend programmatic demo generation to other components.",
  },
  {
    file: "tools/demo.mjs",
    lines: "~127-230",
    what: "Per-tier HTML fixtures (dialogDemoHtml, fieldDemoHtml, etc.) — kernel/trivial-js components get static HTML hand-written here; consumed by tools/demo.mjs.",
  },
  {
    file: "docs/demos/",
    lines: "(directory)",
    what: "300+ hand-authored demo HTML files (FT7 batches; docs/demos/*-rtl-{he,en,fa}.html are build-rtl vendor outputs). NO tool owns the rest currently — they're static templates. To make programmatic, extend tools/build-demo.mjs to emit each variant from upstream examples/radix/<name>-<variant>.tsx.",
  },
]

// ---------- scan -------------------------------------------------------------
function classify(path) {
  for (const p of PROGRAMMATIC_PATTERNS) if (p.test(path)) return { kind: "programmatic", tool: p.tool, source: p.source }
  for (const p of TOOL_SOURCE_PATTERNS) if (p.test(path)) return { kind: "tool-source", note: p.note }
  for (const p of HAND_AUTHORED_PATTERNS) if (p.test(path)) return { kind: "hand-authored", owner: p.owner }
  return { kind: "unknown" }
}

// Walk the repo, skipping common artifacts. Skip supports two forms:
//   exact filename match (e.g. ".git", "node_modules")
//   path-prefix match    (e.g. "tools/contracts/out")
// Note: dist/ is NOT skipped — dist/components/*.html is git-tracked and
// represents the live library output. tools/contracts/out IS skipped —
// those are runtime oracle artifacts, not part of the repo's source.
function walk(root, skip = [
  ".git", "node_modules", ".upstream",
  "tools/contracts/out",
]) {
  const out = []
  // Normalize root for prefix matching (join(".", "x") already yields "x",
  // so no "./" stripping is needed — kept simple on purpose).
  const rootPrefix = root === "." ? "" : root.replace(/\/$/, "")
  const shouldSkip = (p) => {
    const rel = rootPrefix ? (p.startsWith(rootPrefix + "/") ? p.slice(rootPrefix.length + 1) : p) : p
    for (const s of skip) {
      if (s.includes("/")) {
        // path-prefix match against the relative path
        if (rel === s || rel.startsWith(s + "/")) return true
      } else {
        const segments = rel.split("/")
        if (segments.includes(s)) return true
      }
    }
    return false
  }
  const recurse = (dir) => {
    let entries
    try { entries = readdirSync(dir, { withFileTypes: true }) } catch { return }
    for (const e of entries) {
      const p = join(dir, e.name)
      if (shouldSkip(p)) continue
      if (e.isDirectory()) recurse(p)
      else out.push(p)
    }
  }
  recurse(root)
  return out.sort()
}

// ---------- drift detection -------------------------------------------------
// A "drift" is a tool-generated file that has been MODIFIED in git
// working tree (status " M" or "M " — i.e. it differs from HEAD).
// UNTRACKED files ("??") are pipeline outputs that haven't been
// committed yet — those are NOT drift, they're the normal state after
// `make build`. Only flag files that someone touched after the tool
// generated them.
function detectDrift(programmatic) {
  let modified = new Set()
  try {
    // --untracked-files=no ensures we only get tracked-but-modified files.
    const out = execSync("git status --porcelain --untracked-files=no", { encoding: "utf8" })
    for (const line of out.split("\n").filter(Boolean)) {
      // porcelain: "XY path" where first char is staged status, second is
      // unstaged. We only care about files that differ from HEAD, so any
      // status with M (modified) or D (deleted) in either column counts.
      const x = line[0]
      const y = line[1]
      if (x !== "M" && y !== "M" && x !== "D" && y !== "D") continue
      const rest = line.slice(3)
      const path = rest.includes(" -> ") ? rest.split(" -> ")[1] : rest
      modified.add(path.replace(/^"|"$/g, ""))
    }
  } catch { /* git not available */ }
  // (walk() yields prefix-free paths when root is ".", so no "./" strip)
  const norm = (p) => p
  return programmatic.filter((e) => modified.has(norm(e.path)))
}

// ---------- discover mode ----------------------------------------------------
// Detect new files (untracked + added in git) and suggest which pattern
// they should be added to. Suggestions are derived from:
//   1. Sibling analysis — files in the same directory that DO match an
//      existing pattern (we infer the new file belongs to the same
//      category / tool).
//   2. Path heuristics — dist/, docs/site/, tools/*.mjs, etc.
//
// Output is a ready-to-paste JS snippet for the operator to add to
// PROGRAMMATIC_PATTERNS / TOOL_SOURCE_PATTERNS / HAND_AUTHORED_PATTERNS.
const HEURISTIC_HINTS = [
  // Specific patterns FIRST — the catch-all below shadows any specific
  // dist/ pattern placed after it (first-match wins), so a dist/components/
  // rtl file used to be suggested as "emitter OR demo" instead of build-rtl.
  { test: (p) => /^dist\/components\/[^/]+-rtl-(en|he|fa)\.html$/.test(p),
    kind: "programmatic", tool: "tools/build-rtl.mjs", source: "examples/aria/<name>-rtl.tsx" },
  { test: (p) => /^docs\/demos\/[^/]+-rtl-(en|he|fa)\.html$/.test(p),
    kind: "programmatic", tool: "tools/build-rtl.mjs", source: "examples/aria/<name>-rtl.tsx" },
  { test: (p) => /^docs\/demos\/[^/]+-demo\.html$/.test(p),
    kind: "programmatic", tool: "tools/build-demo.mjs", source: "examples/radix/<name>-demo.tsx" },
  { test: (p) => /^dist\/glue\//.test(p),
    kind: "programmatic", tool: "tools/demo.mjs", source: "src/kernel/*-glue.js" },
  // Catch-all: any HTML file under dist/ is a programmatic build artifact.
  // The specific patterns above catch the known subdirs (components, glue);
  // this fallback handles new subdirs (e.g. dist/widgets/) that the
  // specific patterns haven't been updated for yet. Review with the
  // operator if a new dist/ subdir appears — it should map to a specific
  // emitter/build tool.
  { test: (p) => /^dist\/.+\.html$/.test(p),
    kind: "programmatic", tool: "src/emitter/index.mjs OR tools/demo.mjs (per-tier fixture)",
    source: "src/registry/ir/*.json + probes/t{6,7,8,9}/*" },
  { test: (p) => /^docs\/site\/[^/]+\.html$/.test(p),
    kind: "programmatic", tool: "tools/docs-build.mjs", source: "apps/v4/content/docs/components/*/*.mdx" },
  { test: (p) => /^src\/registry\/ir\/[^/]+\.json$/.test(p),
    kind: "programmatic", tool: "src/converter/index.mjs", source: "apps/v4/registry/bases/radix/ui/*.tsx" },
  { test: (p) => /^tools\/[^/]+\.mjs$/.test(p),
    kind: "tool-source", note: "pipeline orchestrator + builder tool" },
  { test: (p) => /^scripts\/[^/]+\.(sh|js|mjs)$/.test(p),
    kind: "tool-source", note: "scripts/*.sh|js|mjs — ad-hoc scripts; consider promoting to tools/ if used by Makefile" },
  { test: (p) => /^src\/converter\/[^/]+\.mjs$/.test(p),
    kind: "tool-source", note: "src/converter — registry → IR" },
  { test: (p) => /^src\/emitter\/[^/]+\.mjs$/.test(p),
    kind: "tool-source", note: "src/emitter — IR → dist/components + slot CSS" },
  { test: (p) => /^src\/docs\/[^/]+\.mjs$/.test(p),
    kind: "tool-source", note: "src/docs — JSX runtime used by MDX compile" },
  { test: (p) => /^src\/runtime\/[^/]+\.(mjs|js)$/.test(p),
    kind: "tool-source", note: "src/runtime — interactive runtime (copied to dist/shadless.js)" },
  { test: (p) => /^vendor\//.test(p),
    kind: "hand-authored", owner: "human (vendor — manually vendored from upstream)" },
  { test: (p) => /^probes\//.test(p),
    kind: "hand-authored", owner: "human (test fixture)" },
  { test: (p) => /^docs\/demos\//.test(p),
    kind: "hand-authored", owner: "human (FT7 demo batch — extend build-demo.mjs to make programmatic)" },
  { test: (p) => /^docs\/content\/[^/]+\.mdx$/.test(p),
    kind: "hand-authored", owner: "human (guide source — compiled by docs-build)" },
  { test: (p) => /^src\/registry\/pin\.json$/.test(p),
    kind: "hand-authored", owner: "human (commit hash + vendor SHA256)" },
]

function detectNewFiles() {
  const out = []
  try {
    // --untracked-files=all ensures each file is listed individually
    // (not aggregated under its parent directory).
    const status = execSync("git status --porcelain --untracked-files=all", { encoding: "utf8" })
    for (const line of status.split("\n").filter(Boolean)) {
      // ?? = untracked, A  = added (staged). Both = new since HEAD.
      const xy = line.slice(0, 2)
      if (xy !== "??" && xy[0] !== "A") continue
      const path = line.slice(3).replace(/^"|"$/g, "").replace(/ -> .*/, "")
      // Skip directories (git lists them with trailing /).
      if (path.endsWith("/")) continue
      out.push(path)
    }
  } catch { /* git not available */ }
  return out
}

// Sibling-based suggestion: find files in the SAME DIRECTORY (not the
// whole subtree — that would overweight huge dirs like docs/site/) that
// already have a pattern, and propose the dominant category.
function suggestFromSiblings(newPath, allFiles, classified) {
  // Get the parent directory of newPath. Sibling files share this dir
  // but are NOT inside any subdirectory of it.
  const slash = newPath.lastIndexOf("/")
  const dir = slash === -1 ? "" : newPath.slice(0, slash + 1)
  const siblings = allFiles.filter((p) => {
    if (p === newPath) return false
    const s = p.lastIndexOf("/")
    const pdir = s === -1 ? "" : p.slice(0, s + 1)
    return pdir === dir
  })
  const matched = siblings.map((p) => classified.get(p)).filter((s) => s && s.kind !== "unknown")
  if (matched.length === 0) return null
  // Pick the most common kind/tool among siblings
  const counts = new Map()
  for (const m of matched) {
    const k = JSON.stringify({ kind: m.kind, tool: m.tool || m.note || m.owner })
    counts.set(k, (counts.get(k) || 0) + 1)
  }
  const [topKey, topCount] = [...counts.entries()].sort((a, b) => b[1] - a[1])[0]
  const top = JSON.parse(topKey)
  return {
    method: "sibling",
    confidence: topCount / siblings.length,
    suggestion: top,
    siblings_sampled: matched.length,
    total_siblings: siblings.length,
  }
}

function suggestFromHeuristics(newPath) {
  for (const h of HEURISTIC_HINTS) {
    if (h.test(newPath)) return { method: "heuristic", confidence: 0.8, suggestion: { kind: h.kind, ...(h.tool ? { tool: h.tool } : {}), ...(h.source ? { source: h.source } : {}), ...(h.owner ? { owner: h.owner } : {}), ...(h.note ? { note: h.note } : {}) } }
  }
  return null
}

function runDiscover(allFiles, classified) {
  const newFiles = detectNewFiles()
  if (newFiles.length === 0) {
    console.log("No new files detected in git working tree.")
    return
  }
  console.log(`Discovered ${newFiles.length} new file${newFiles.length === 1 ? "" : "s"} (untracked + added since HEAD):\n`)
  // Group by current classification
  const matched = []
  const unmatched = []
  const classifiedMap = new Map(classified.map((c) => [c.path, c]))
  for (const p of newFiles) {
    const c = classifiedMap.get(p)
    if (c && c.kind !== "unknown") matched.push({ path: p, ...c })
    else unmatched.push(p)
  }
  if (matched.length) {
    console.log("ALREADY CLASSIFIED (matches existing pattern)")
    console.log("-".repeat(72))
    for (const m of matched) console.log(`  [${m.kind}] ${m.path}`)
    console.log("")
  }
  if (unmatched.length) {
    console.log("UNCLASSIFIED (needs a new pattern)")
    console.log("-".repeat(72))
    // Build suggestions
    const suggestions = []
    for (const p of unmatched) {
      const sib = suggestFromSiblings(p, allFiles, classifiedMap)
      const heu = suggestFromHeuristics(p)
      suggestions.push({ path: p, sibling: sib, heuristic: heu })
    }
    // Print suggestions grouped by path
    for (const s of suggestions) {
      console.log(`  ${s.path}`)
      if (s.sibling) {
        console.log(`    sibling-based: ${Math.round(s.sibling.confidence * 100)}% confidence (${s.sibling.siblings_sampled} siblings match)`)
        console.log(`      kind:  ${s.sibling.suggestion.kind}`)
        if (s.sibling.suggestion.tool) console.log(`      tool:  ${s.sibling.suggestion.tool}`)
        if (s.sibling.suggestion.note) console.log(`      note:  ${s.sibling.suggestion.note}`)
        if (s.sibling.suggestion.owner) console.log(`      owner: ${s.sibling.suggestion.owner}`)
      }
      if (s.heuristic) {
        console.log(`    heuristic: ${Math.round(s.heuristic.confidence * 100)}% confidence`)
        console.log(`      kind:  ${s.heuristic.suggestion.kind}`)
        if (s.heuristic.suggestion.tool) console.log(`      tool:  ${s.heuristic.suggestion.tool}`)
        if (s.heuristic.suggestion.source) console.log(`      source: ${s.heuristic.suggestion.source}`)
        if (s.heuristic.suggestion.note) console.log(`      note:  ${s.heuristic.suggestion.note}`)
        if (s.heuristic.suggestion.owner) console.log(`      owner: ${s.heuristic.suggestion.owner}`)
      }
      if (!s.sibling && !s.heuristic) {
        console.log(`    NO SUGGESTION — needs manual categorization`)
      }
      console.log("")
    }
    // Emit a copy-paste JS snippet for the highest-confidence suggestion
    console.log("SUGGESTED PATTERN ADDITIONS (copy-paste into audit-boundary.mjs):")
    console.log("-".repeat(72))
    for (const s of suggestions) {
      const use = s.heuristic || s.sibling
      if (!use) continue
      const sug = use.suggestion
      const entry = sug.tool ? `{ test: (p) => /* path to ${s.path} */, tool: "${sug.tool}", source: "${sug.source || ""}" },`
        : sug.note ? `{ test: (p) => /* path to ${s.path} */, note: "${sug.note}" },`
        : `{ test: (p) => /* path to ${s.path} */, owner: "${sug.owner}" },`
      console.log(`  ${entry}`)
    }
  }
}

// ---------- output -----------------------------------------------------------
const argv = process.argv.slice(2)
const strict = argv.includes("--strict")
const discover = argv.includes("discover")

const all = walk(".")
const classified = all.map((p) => ({ path: p, ...classify(p) }))

if (discover) {
  // discover mode: focus on new files only, skip the full report.
  runDiscover(all, classified)
  process.exit(0)
}

const programmatic = classified.filter((c) => c.kind === "programmatic")
const toolSource = classified.filter((c) => c.kind === "tool-source")
const handAuthored = classified.filter((c) => c.kind === "hand-authored")
const unknown = classified.filter((c) => c.kind === "unknown")

if (strict) {
  const norm = (p) => p.replace(/^\.\//, "")
  const drift = detectDrift(programmatic)
  console.log(JSON.stringify({
    programmatic: programmatic.length,
    tool_source: toolSource.length,
    hand_authored: handAuthored.length,
    unknown: unknown.length,
    llm_patch_points: LLM_PATCH_POINTS.length,
    drift: drift.map((d) => ({ path: norm(d.path), tool: d.tool })),
  }, null, 2))
  process.exit(drift.length === 0 ? 0 : 1)
} else {
  // Human-readable report
  console.log("PROGRAMMATIC ZONE — regenerated by tools on `make build`")
  console.log("=" .repeat(72))
  // Group by tool
  const byTool = new Map()
  for (const e of programmatic) {
    const k = e.tool || "(unknown tool)"
    if (!byTool.has(k)) byTool.set(k, [])
    byTool.get(k).push(e.path)
  }
  for (const [tool, paths] of byTool) {
    console.log("")
    console.log(`[${tool}]  (${paths.length} file${paths.length === 1 ? "" : "s"})`)
    for (const p of paths.slice(0, 8)) console.log(`  ${p}`)
    if (paths.length > 8) console.log(`  …and ${paths.length - 8} more`)
  }
  console.log("")
  console.log("")
  console.log("")
  console.log("")
  console.log("HAND-AUTHORED ZONE — LLM/human edits expected, no script owns them")
  console.log("=".repeat(72))
  const byOwner = new Map()
  for (const e of handAuthored) {
    const k = e.owner || "(unowned)"
    if (!byOwner.has(k)) byOwner.set(k, [])
    byOwner.get(k).push(e.path)
  }
  for (const [owner, paths] of byOwner) {
    console.log("")
    console.log(`[${owner}]  (${paths.length} file${paths.length === 1 ? "" : "s"})`)
    for (const p of paths.slice(0, 8)) console.log(`  ${p}`)
    if (paths.length > 8) console.log(`  …and ${paths.length - 8} more`)
  }
  console.log("")
  console.log("")
  console.log("TOOL SOURCE — hand-written code that owns the PROGRAMMATIC ZONE")
  console.log("=".repeat(72))
  for (const p of TOOL_SOURCE_PATTERNS) {
    console.log("")
    console.log(`[${p.note}]`)
    const re = p.test
    const matches = toolSource.filter((e) => re(e.path))
    if (matches.length) {
      for (const m of matches.slice(0, 8)) console.log(`  ${m.path}`)
      if (matches.length > 8) console.log(`  …and ${matches.length - 8} more`)
    }
  }
  console.log("")
  console.log("")
  console.log("LLM PATCH POINTS — explicit hand-coded regions inside tool source")
  console.log("=".repeat(72))
  for (const p of LLM_PATCH_POINTS) {
    console.log("")
    console.log(`[${p.file}${p.lines ? `:${p.lines}` : ""}]`)
    console.log(`  ${p.what}`)
  }
  console.log("")
  console.log("")
  console.log("DRIFT — tool-generated files with uncommitted changes")
  console.log("=".repeat(72))
  console.log("(Tool-generated file is \"drift\" if git status shows it as")
  console.log(" modified. NOTE: this is noisy right after `make build` — every")
  console.log(" regenerated file appears as drift until committed. Run")
  console.log(" `git status` to see if drift is from a fresh build vs a")
  console.log(" manual edit. For CI gating, use --strict mode.)")
  const norm = (p) => p.replace(/^\.\//, "")
  const drift = detectDrift(programmatic)
  if (drift.length === 0) {
    console.log("")
    console.log("(none)")
  } else if (drift.length > 30) {
    console.log("")
    console.log(`(${drift.length} files — showing first 30; run \`git status\` for full list)`)
    for (const d of drift.slice(0, 30)) console.log(`  ${norm(d.path)}  (${d.tool})`)
  } else {
    console.log("")
    for (const d of drift) console.log(`  ${norm(d.path)}  (${d.tool})`)
  }
  console.log("")
  console.log("")
  console.log("SUMMARY")
  console.log("=".repeat(72))
  console.log(`  programmatic: ${programmatic.length} files (regenerated by ${byTool.size} tools)`)
  console.log(`  tool source: ${toolSource.length} files (hand-written code that owns the PROGRAMMATIC zone)`)
  console.log(`  hand-authored: ${handAuthored.length} files (in ${byOwner.size} categories)`)
  console.log(`  unknown: ${unknown.length} files (no pattern matched)`)
  console.log(`  LLM patch points: ${LLM_PATCH_POINTS.length}`)
  console.log(`  drift: ${drift.length}`)
  if (unknown.length > 0) {
    console.log("")
    console.log("UNKNOWN files (no pattern matched — add to PROGRAMMATIC_PATTERNS or HAND_AUTHORED_PATTERNS):")
    for (const u of unknown.slice(0, 20)) console.log(`  ${u.path}`)
    if (unknown.length > 20) console.log(`  …and ${unknown.length - 20} more`)
  }
}
